for prefix, text in development_results_replacements:
    set_text(find(prefix), text)

performance_heading = find("Rendimiento comparativo de los modelos")
performance_h1 = insert_after(performance_heading, "La evaluación comparativa se reporta por horizonte. En h=1, Ridge con variables históricas registró RMSE de 502.11 y MAE de 325.98, frente a RMSE de 595.02 y MAE de 400.19 de la persistencia del último valor semanal observado. En h=4, el promedio móvil de cuatro semanas fue la alternativa con menor RMSE descriptivo (652.52) y MAE de 427.63. Las métricas no se combinan entre horizontes.", "Normal")
insert_after(performance_h1, "Para la planeación de cuatro semanas, el pipeline suma las estimaciones directas h=1, h=2, h=3 y h=4. Esta salida se conserva como consolidado presupuestal histórico y no equivale a un modelo mensual independiente. La comparación incluye 21 configuraciones en 16 orígenes comunes, con 336 registros consolidados.", "Normal")

